  const block=document.createElement('section');block.className='textbook-section';block.innerHTML='<h3>候选联系</h3><p>保留原整理的方向、场景和来源；两端身份继续作为候选。</p><button type="button" id="b06-inbox-relations" data-b06-relations>查看 '+data.candidateRelations.length+' 条候选联系</button>';
